let seedPromise: Promise<ScriptCatalogueRecord[]> | undefined;

export async function loadInitialScriptCatalogue(): Promise<ScriptCatalogueRecord[]> {
  if (!seedPromise) {
    seedPromise = (async () => {
      const decode = globalThis.atob;
      const Decompression = (globalThis as unknown as {
        DecompressionStream?: new (format: string) => TransformStream;
      }).DecompressionStream;
      if (typeof decode !== "function" || typeof Decompression !== "function") {
        throw new Error("The Worker runtime does not support the compressed script catalogue seed.");
      }
      const binary = decode(COMPRESSED_SEED);
      const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0));
      const compressed = new Response(bytes).body;
      if (!compressed) throw new Error("Unable to read the compressed script catalogue seed.");
      const stream = compressed.pipeThrough(new Decompression("gzip"));
      const records = JSON.parse(await new Response(stream).text()) as unknown;
      if (!Array.isArray(records) || records.length === 0) {
        throw new Error("The bundled script catalogue seed is empty.");
      }
      return (records as ScriptCatalogueRecord[]).map((record) => {
        const normalized = { ...record };
        if (normalized.language === "Not recorded in published catalogue") delete normalized.language;
        if (normalized.runAs === "Not recorded in published catalogue") delete normalized.runAs;
        if (Array.isArray(normalized.tags) && normalized.tags.length === 0) delete normalized.tags;
        return normalized;
      });
    })();
  }
  return seedPromise;
}
